globalThis.KENGURU_GRADE_CONDITIONS = {"2004":{"1":{"question":"Какая из букв слова КЕНГУРУ имеет самый большой номер в русском алфавите?","choices":["К","Е","Г","У","Р"]},"2":{"question":"У Гарри Поттера есть волшебные очки, в которых он видит все зеленое – белым, а все белое – зеленым. Гарри посмотрел через эти очки на прямоугольник, изображенный справа. Что он увидел?","image":"assets/grade-conditions/2004/task-02.webp","imageWidth":938,"imageHeight":259},"3":{"question":"Дима сложил квадратный листок бумаги пополам, потом еще раз и еще раз. В центре того, что получилось, он проделал дырку, а потом снова развернул лист. Сколько дырок он увидел?","choices":["2","3","4","6","8"]},"4":{"question":"Чтобы открыть секретную дверь в пещеру гномов, нужно заполнить четырьмя магическими знаками таблицу 4×4 так, чтобы в каждой строчке и каждом столбце встречался каждый из знаков. Маленькой гномик начал заполнять эту таблицу. Какой знак он должен поставить в клеточку, отмеченную знаком вопроса?","image":"assets/grade-conditions/2004/task-04.webp","imageWidth":946,"imageHeight":225},"5":{"question":"Наши предки называли число, равное миллиону миллионов, словом «легион». Если разделить миллион легионов на легион миллионов, то получится","choices":["легион","миллион","миллион миллионов","легион легионов","1"]},"6":{"question":"Среди этих пяти карточек есть три одинаковых. Какие?","choices":["1, 2 и 4","2, 3 и 5","1, 3 и 4","2, 4 и 5","3, 4 и 5"],"image":"assets/grade-conditions/2004/task-06.webp","imageWidth":864,"imageHeight":131},"7":{"question":"На каждой кочке в маленьком болотце сидят не меньше, чем по 3 лягушки, а всего лягушек – 145. Тогда число кочек в этом болотце не может равняться","choices":["1","23","31","44","55"]},"8":{"question":"Сумма вычитаемого, уменьшаемого и разности равна 2004. Тогда уменьшаемое равно","choices":["1002","501","384","204","167"]},"9":{"question":"Если кенгуру научится прыгать в 1,5 раза дальше, чем умеет, ему понадобится ровно 6 прыжков, чтобы добраться до тенистого дерева. За сколько прыжков кенгуру может это сделать сейчас?","choices":["3","4","6","9","невозможно определить"]},"10":{"question":"У двузначного числа n цифра десятков в два раза больше, чем цифра единиц. Тогда число n обязательно","choices":["четное","нечетное","меньше 20","делится на 3","делится на 6"]},"11":{"question":"Какую из фигурок A — E нельзя составить из двух одинаковых деталей, изображенных справа, если эти детали не переворачивать тыльной стороной вверх?","choices":["Фигурка A","Фигурка B","Фигурка C","Фигурка D","Фигурка E"],"image":"assets/grade-conditions/2004/task-11.svg","imageWidth":222,"imageHeight":93,"choiceImages":["assets/grade-conditions/2004/choice-11-1.webp","assets/grade-conditions/2004/choice-11-2.webp","assets/grade-conditions/2004/choice-11-3.webp","assets/grade-conditions/2004/choice-11-4.webp","assets/grade-conditions/2004/choice-11-5.webp"]},"12":{"question":"Четверо ребят обсуждали ответ к задаче. Коля сказал: «Это число 9». Роман: «Это простое число». Катя: «Это четное число». А Наташа сказала, что это число – 15. Назовите правильный ответ, если и мальчики, и девочки ошиблись ровно по одному разу.","choices":["1","2","3","9","15"]},"13":{"question":"Остаток от деления 100 на некоторое число равен 4, а при делении 90 на это же число в остатке получается 18. На какое число делили?","choices":["18","32","24","36","48"]},"14":{"question":"В примере на сложение □ + □ + ○○ = △△△ различные фигурки заменяют различные цифры. Какую цифру заменяет квадратик?","choices":["9","8","7","6","5"]},"15":{"question":"От кубика, склеенного из бумаги, отрезали уголок. Если этот кубик разрезать по некоторым ребрам и развернуть, то получится одна из фигурок А – Е. Какая?","image":"assets/grade-conditions/2004/task-15.webp","imageWidth":956,"imageHeight":283},"16":{"question":"На некотором острове необычайно регулярный климат: по понедельникам и средам всегда идут дожди, по субботам туман, зато в остальные дни солнечно. Утром какого дня недели нужно начать свой отдых на этом острове группе туристов, если они хотят пробыть там 44 дня и захватить при этом как можно больше солнечных дней?","choices":["в понедельник","в среду","в четверг","в пятницу","во вторник"]},"17":{"question":"Разглядывая семейный альбом, Ванечка обнаружил, что у него 4 прабабушки и 4 прадедушки. А сколько прабабушек и прадедушек имели его прабабушки и прадедушки все вместе?","choices":["16","32","64","128","256"]},"18":{"question":"В ряд выписали 11 натуральных чисел так, что сумма любых трех соседних чисел равна 21. На первом месте стоит число 7, а на девятом – 6. Какое число стоит на втором месте?","choices":["7","8","6","10","21"]},"19":{"question":"На конкурсе в летнем математическом лагере для победителей «Кенгуру» (в польском городе Закопане) участникам предлагалось 10 задач. За каждый верный ответ засчитывалось 5 очков, а за каждый неверный – снималось 3 очка. Петер получил 34 очка. Сколько из его десяти решений оказались ошибочными?","choices":["1","2","3","4","5"]},"20":{"question":"Шесть монет положены на стол так, как показано на левом рисунке. За один ход разрешается переложить одну монету так, чтобы в новом положении она касалась не менее, чем двух других монет. За какое наименьшее число ходов можно уложить монеты так, как показано на правом рисунке?","choices":["1","2","3","4","5"],"image":"assets/grade-conditions/2004/task-20.webp","imageWidth":342,"imageHeight":136},"21":{"question":"Герой повести Носова «Незнайка в Солнечном городе» Пачкуля Пестренький придерживался твердого принципа: «Никогда не умываться и ничему не удивляться». Если он отступит от своего принципа, то он обязательно","choices":["Станет удивляться всему подряд","Будет каждый день умываться","Каждый день будет умываться или удивляться","Хоть раз умоется или чему-то удивится","Каждый день будет умываться и всему удивляться"]},"22":{"question":"Из чисел, квадраты которых делятся на 24, выбрали самое маленькое. Чему равна сумма цифр этого числа?","choices":["2","3","6","9","10"]},"23":{"question":"Клетки некоторой квадратной таблицы заполняют последовательными натуральными числами, начиная с 1. Это делают «змейкой», как показано на рисунке. Какое из следующих чисел не может оказаться в правой верхней клеточке такой таблицы?","choices":["128","81","256","961","1024"],"image":"assets/grade-conditions/2004/task-23.webp","imageWidth":225,"imageHeight":226},"24":{"question":"Число 111…111 (2004 единицы) разделили на 3. Сколько нулей получилось в записи частного?","choices":["670","669","668","667","665"]},"25":{"question":"У числа 125 любые две цифры отличаются не меньше, чем в два раза. Сколько всего трехзначных чисел с ненулевыми цифрами обладают этим свойством?","choices":["14","42","48","56","84"]},"26":{"question":"Костя собирает марки с изображениями машин и птиц. Сначала у него было поровну марок обоих видов, но потом он обменялся несколькими марками со своим приятелем. В результате этого обмена число марок с птицами уменьшилось на 5%, а число марок с машинами увеличилось на 15%, причем марок с машинами стало на 24 больше, чем с птицами. Сколько марок с птицами осталось у Кости?","choices":["6","24","114","120","138"]},"27":{"question":"Трое мальчиков участвуют в велосипедных гонках. Питер стартовал первым, Томми – вторым, а Дэвид – третьим. Положение Питера в гонке менялось 8 раз, а положение Дэвида – 3 раза. Тогда положение Томми могло меняться","choices":["1 раз","2 раза","8 раз","9 раз","ни разу"]},"28":{"question":"Крыша покрыта одинаковыми прямоугольными листами кровли, которые уложены в 8 рядов (снизу вверх). Каждый следующий ряд перекрывает предыдущий на 0,1 своей ширины. Какая часть крыши покрыта в два слоя?","image":"assets/grade-conditions/2004/task-28.webp","imageWidth":866,"imageHeight":74},"29":{"question":"Назовем набор из нескольких (больше восьми) натуральных чисел «хорошим», если сумма всех этих чисел равна 196, а сумма любых восьми из них не больше, чем 24. Сколько чисел в самом коротком из хороших наборов?","choices":["32","64","65","66","196"]},"30":{"question":"В треугольнике отмечены вершины, и, кроме того, две точки на одной стороне и по одной точке на каждой из остальных сторон (всего отмечено 7 точек). Сколько треугольников с вершинами в отмеченных точках можно построить?","choices":["12","26","29","31","35"],"image":"assets/grade-conditions/2004/task-30.webp","imageWidth":179,"imageHeight":186}}};
globalThis.KENGURU_GRADE_SOLUTION_STEPS = {};
